using SASZombieAssaultTD.Engine.Events;using SASZombieAssaultTD.Engine.Diagnostics;  using SASZombieAssaultTD.Engine.Events; using SASZombieAssaultTD.Engine.Player; using SASZombieAssaultTD.Engine.Waves; using SASZombieAssaultTD.Engine.ECS; using System; using System.Collections.Generic;  namespace SASZombieAssaultTD.Engine.HUD {     public sealed class HUDController : IGameSystem     {         private readonly Dictionary<string, HUDComponent> _elements = new();          public HUDController()         {         }          public void Initialize()         {             // Subscribe to PlayerSystem events (use available PlayerEvents static API)             PlayerEvents.OnCashChanged += (c) => { /* hook into cash UI if needed */ };              // Initial sync (guard against missing systems) //             try             {                 var ps = PlayerSystem.Instance;                 if (ps != null && ps.State != null)                 {                     SyncHealth(ps.State.Lives, ps.State.MaxLives);                 }             } //             catch             {                 // ignore             }              SyncInventory();         }          public void Cleanup()         {             // Unsubscribe from events if we subscribed any named handlers         }          // IGameSystem compatibility         public void Update(float deltaTime) { }         public void Shutdown() { Cleanup(); }         public bool IsActive { get; set; } = true;          // -----------------------------         // EVENT HANDLERS         // -----------------------------          private void OnHealthChanged(int current, int max)         {             SyncHealth(current, max);         }          private void OnWaveStarted(int waveNumber)         {             SyncWave(waveNumber);         }          private void OnInventoryChanged()         {             SyncInventory();         }          // -----------------------------         // SYNC METHODS         // -----------------------------          private void SyncHealth(int current, int max)         {             float pct = (float)current / max;              if (_elements.TryGetValue("health_text", out var text))                 text.SetText($"{current}/{max}");              if (_elements.TryGetValue("health_bar", out var bar))                 bar.SetFillAmount(pct); // Windsurf implements this         }          private void SyncWave(int wave)         {             if (_elements.TryGetValue("wave_text", out var text))                 text.SetText($"Wave {wave}");         }          private void SyncInventory()         {             var inv = PlayerSystem.Instance.Inventory;              UpdateSlot("item_slot_1", inv.GetItemAt(0));             UpdateSlot("item_slot_2", inv.GetItemAt(1));             UpdateSlot("item_slot_3", inv.GetItemAt(2));         }          private void UpdateSlot(string slotId, SASZombieAssaultTD.Engine.Components.ItemInstance item)         {             if (!_elements.TryGetValue(slotId, out var slot))                 return;              if (item == null)             {                 slot.SetImage("Assets/HUD/item_slot.png");                 return;             }              slot.SetImage(item.IconPath);              if (_elements.TryGetValue(slotId + "_text", out var text))                 text.SetText(item.Quantity.ToString());         }     }  //     internal class HUDComponent     {     } }
